(()=>{const box=document.querySelector('.hero-countdown');if(!box)return;const target=Date.parse('2027-01-15T00:00:00+05:30');let timer;function update(){const seconds=Math.max(0,Math.floor((target-Date.now())/1000));const values={days:Math.floor(seconds/86400),hours:Math.floor(seconds/3600)%24,minutes:Math.floor(seconds/60)%60,seconds:seconds%60};Object.entries(values).forEach(([key,n])=>box.querySelector(`[data-count="${key}"]`).textContent=String(n).padStart(2,'0'));if(seconds===0){document.querySelector('.countdown-status').textContent='The voyage is underway';clearInterval(timer)}}update();timer=setInterval(update,1000);document.addEventListener('visibilitychange',()=>{clearInterval(timer);if(!document.hidden){update();timer=setInterval(update,1000)}})})();
